const entrada = $input.first()?.json ?? {};
let datos = entrada.body ?? entrada;
if (typeof datos === 'string') { try { datos = JSON.parse(datos); } catch { datos = {}; } }
const f = { ...entrada, ...datos };
const codigo = String(f.codigo ?? '');
const nombre = String(f.nombre ?? '');
const contacto = String(f.contacto ?? '');
const fecha = String(f.fecha ?? '');
const hora = String(f.hora ?? '');
const personas = Number(f.numeroPersonas ?? 0);
const comentarios = String(f.comentarios ?? '').trim();
if (!codigo || !nombre || !contacto || !fecha || !hora || !Number.isInteger(personas)) throw new Error('La solicitud de reserva está incompleta.');
const mensaje = '📅 NUEVA SOLICITUD DE RESERVA\n\n' + 'Referencia: ' + codigo + '\n' + '👤 ' + nombre + '\n' + '📞 ' + contacto + '\n' + '🗓 ' + fecha + ' · ' + hora + '\n' + '👥 ' + personas + ' personas' + (comentarios ? '\n\n📝 ' + comentarios : '') + '\n\nPendiente de confirmar en Administración.';
return [{ json: { codigo, nombre, contacto, fecha, hora, personas, comentarios, mensaje } }];
